/// <summary>
/// Provides a simple retry strategy that re-invokes an operation until it succeeds or the attempt limit is exhausted.
/// </summary>

/// <summary>
/// Invokes <paramref name="operation"/> and retries it until it succeeds or the attempt limit is reached.
/// </summary>
/// <typeparam name="T">The type of value produced by the operation.</typeparam>
/// <param name="operation">The operation to execute.</param>
/// <param name="maxAttempts">The maximum number of attempts to make.</param>
/// <returns>The value returned by the first successful invocation of <paramref name="operation"/>.</returns>
/// <exception cref="InvalidOperationException">Thrown when the operation does not succeed within <paramref name="maxAttempts"/> attempts.</exception>
